 * Parses build-graph text into a map of task names to costs and a map of
 * task names to their (deduplicated, first-seen order) dependency names.
 * Every syntax problem is reported against the line that caused it, and
 * throws as soon as it is found; the one exception is a `dep` line naming a
 * task nothing declares, which is only detectable once every line has been
 * read, so that check runs last, in the order the names were first used.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const usedNames = []

  lines.forEach((raw, index) => {
    const lineNo = index + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return

    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costText)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, Number(costText))
      if (!deps.has(name)) deps.set(name, [])
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const [, name, ...dependencyNames] = words
      usedNames.push(name, ...dependencyNames)
      const list = deps.get(name) ?? []
      for (const dependencyName of dependencyNames) {
        if (!list.includes(dependencyName)) list.push(dependencyName)
      }
      deps.set(name, list)
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
  })

  for (const name of usedNames) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`)
    }
  }

  for (const name of tasks.keys()) {
    if (!deps.has(name)) deps.set(name, [])
  }

  return { tasks, deps }
}
"}

