 * Finds the first cycle a depth-first search discovers, starting from each
 * task in ascending name order and walking each task's dependencies in
 * ascending name order. Returns the cycle as an array of names, from the
 * re-entered task through the search stack and back to it, or null when the
 * graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const onStack = new Set()
  const done = new Set()
  const stack = []

  function visit(name) {
    if (onStack.has(name)) {
      const start = stack.indexOf(name)
      return [...stack.slice(start), name]
    }
    if (done.has(name)) return null

    onStack.add(name)
    stack.push(name)
    for (const dependency of [...deps.get(name)].sort()) {
      const cycle = visit(dependency)
      if (cycle) return cycle
    }
    stack.pop()
    onStack.delete(name)
    done.add(name)
    return null
  }

  for (const name of names) {
    const cycle = visit(name)
    if (cycle) return cycle
  }
  return null
}

/**
 * Computes each task's start, finish and wave depth. A task's start is the
 * greatest finish among its dependencies (0 when it has none), its finish
 * is its start plus its cost, and its depth is 0 when it has no
 * dependencies or one more than the greatest depth among them. Assumes the
 * graph is acyclic.
 */
export function computeSchedule(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    let s = 0
    let d = 0
    for (const dependency of deps.get(name)) {
      compute(dependency)
      s = Math.max(s, finish.get(dependency))
      d = Math.max(d, depth.get(dependency) + 1)
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  for (const name of tasks.keys()) compute(name)
  return { start, finish, depth }
}
"}

