 * A task's priority is the cost of the longest chain that begins at it: its
 * own cost plus, when something depends on it, the greatest priority among
 * those dependents.
 */
function computePriority(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, dependencyNames] of deps) {
    for (const dependencyName of dependencyNames) {
      dependents.get(dependencyName).push(name)
    }
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      best = Math.max(best, compute(dependent))
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the build graph on a fixed number of workers. At every instant,
 * while a worker is free and some task is ready (every dependency has
 * finished at or before that instant), the ready task with the greatest
 * priority (ties broken by ascending name) starts on the free worker with
 * the smallest index. When nothing more can start, time jumps to the next
 * instant a worker frees up. Assumes the graph is acyclic.
 */
export function packSchedule(tasks, deps, workerCount) {
  const priority = computePriority(tasks, deps)
  const remaining = new Set(tasks.keys())
  const finishTime = new Map()
  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, runs: [] }))
  let currentTime = 0

  const isReady = (name, at) =>
    deps.get(name).every((dependency) => {
      const t = finishTime.get(dependency)
      return t !== undefined && t <= at
    })

  while (remaining.size > 0) {
    let assignedThisRound = true
    while (assignedThisRound) {
      assignedThisRound = false
      const freeIndex = workers.findIndex((worker) => worker.busyUntil <= currentTime)
      if (freeIndex === -1) break

      let chosen = null
      for (const name of remaining) {
        if (!isReady(name, currentTime)) continue
        if (
          chosen === null ||
          priority.get(name) > priority.get(chosen) ||
          (priority.get(name) === priority.get(chosen) && name < chosen)
        ) {
          chosen = name
        }
      }
      if (chosen === null) break

      const start = currentTime
      const finish = start + tasks.get(chosen)
      workers[freeIndex].busyUntil = finish
      workers[freeIndex].runs.push({ name: chosen, start, finish })
      finishTime.set(chosen, finish)
      remaining.delete(chosen)
      assignedThisRound = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (const worker of workers) {
      if (worker.busyUntil > currentTime) next = Math.min(next, worker.busyUntil)
    }
    currentTime = next
  }

  const makespan = finishTime.size === 0 ? 0 : Math.max(...finishTime.values())
  return { workers, makespan }
}
"}

