const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workerCount: Number(argv[1]) }
  }
  throw new CliError(USAGE)
}

function main() {
  const { mode, workerCount } = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
  }

  const output =
    mode === 'waves'
      ? renderWaves(tasks, deps)
      : mode === 'explain'
        ? renderExplain(tasks, deps)
        : renderPack(tasks, deps, workerCount)

  process.stdout.write(output)
}

try {
  main()
} catch (error) {
  if (error instanceof CliError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(error.exitCode)
  }
  throw error
}
